import math
import hashlib

class BloomFilter:
    """
    A Bloom Filter implementation to allow for space-efficient membership testing.

    The design uses a bit array of optimal size calculated from the expected number of items and desired false positive rate.
    The number of hash functions is also calculated to minimize the probability of false positives.
    """

    def __init__(self, expected_items: int, false_positive_rate: float):
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate
        self.bit_array_size = self._optimal_bit_array_size()
        self.num_hash_functions = self._optimal_num_hash_functions()
        self.bit_array = [0] * self.bit_array_size

    def _optimal_bit_array_size(self) -> int:
        """Calculates the optimal size of the bit array."""
        return math.ceil(-(self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _optimal_num_hash_functions(self) -> int:
        """Calculates the optimal number of hash functions."""
        return math.ceil((self.bit_array_size / self.expected_items) * math.log(2))

    def _hashes(self, item: str):
        """Generates hash values using different salt values to simulate multiple hash functions."""
        hash_values = []
        for i in range(self.num_hash_functions):
            hash_value = int(hashlib.md5((item + str(i)).encode()).hexdigest(), 16) % self.bit_array_size
            hash_values.append(hash_value)
        return hash_values

    def add(self, item: str) -> None:
        """Adds an item to the Bloom filter."""
        for hash_value in self._hashes(item):
            self.bit_array[hash_value] = 1

    def contains(self, item: str) -> bool:
        """Checks if an item might be in the Bloom filter."""
        for hash_value in self._hashes(item):
            if self.bit_array[hash_value] == 0:
                return False
        return True

