    A Bloom Filter implementation for probabilistic membership checking.

    This class uses a configurable size of a bit array and a number of hash functions
    calculated based on the expected number of items and the desired false positive rate.
    Hashing is done using basic string-to-byte conversion along with hashlib for cryptographic
    hash functions. The structure allows for efficient membership testing with a trade-off
    in accuracy (false positives possible).
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.expected_items = expected_items
        self.false_positive_rate = false_positive_rate

        # Calculate the size of the bit array (m) and number of hash functions (k)
        self.size = self._calculate_optimal_size()
        self.num_hashes = self._calculate_num_hashes()

        # Create the bit array initialized to 0
        self.bit_array = [0] * self.size

    def _calculate_optimal_size(self) -> int:
        # Using the formula m = - (n * log(p)) / (log(2)^2)
        return int(- (self.expected_items * math.log(self.false_positive_rate)) / (math.log(2) ** 2))

    def _calculate_num_hashes(self) -> int:
        # Using the formula k = (m / n) * log(2)
        return max(1, int((self.size / self.expected_items) * math.log(2)))

    def _hashes(self, item: str) -> list:
        # Generate k unique hash values for the item
        return [int(hashlib.md5((item + str(i)).encode()).hexdigest(), 16) % self.size for i in range(self.num_hashes)]

    def add(self, item: str) -> None:
        # Add an item by setting bits in the bit array based on the hash values
        for idx in self._hashes(item):
            self.bit_array[idx] = 1

    def contains(self, item: str) -> bool:
        # Check if an item may be in the set by checking bits in the bit array
        return all(self.bit_array[idx] for idx in self._hashes(item))

