class BloomFilter:
    """
    A Bloom Filter implementation for probabilistic set membership testing.
    Utilizes a bit array and multiple hash functions to mitigate false positives.
    """

    def __init__(self, expected_items: int, false_positive_rate: float) -> None:
        self.size = self.calculate_bit_array_size(expected_items, false_positive_rate)
        self.hash_count = self.calculate_hash_count(self.size, expected_items)
        self.bit_array = [0] * self.size

    @staticmethod
    def calculate_bit_array_size(n: int, p: float) -> int:
        """Calculate the optimal size of the bit array."""
        return math.ceil((-n * math.log(p)) / (math.log(2) ** 2))

    @staticmethod
    def calculate_hash_count(m: int, n: int) -> int:
        """Calculate the optimal number of hash functions."""
        return max(1, round((m / n) * math.log(2)))

    def add(self, item: str) -> None:
        """Add an item to the Bloom filter."""
        for i in range(self.hash_count):
            index = self.hash(item, i) % self.size
            self.bit_array[index] = 1

    def contains(self, item: str) -> bool:
        """Check if an item is in the Bloom filter."""
        for i in range(self.hash_count):
            index = self.hash(item, i) % self.size
            if self.bit_array[index] == 0:
                return False
        return True

    def hash(self, item: str, seed: int) -> int:
        """Create a hash by combining a seed with the input item."""
        hash_result = hashlib.md5(f"{item}{seed}".encode()).hexdigest()
        return int(hash_result, 16)

